"""Execute actual privileged listener with deterministic platform and audio boundaries."""
from pathlib import Path
import subprocess,tempfile
files={
'io/tvos/SystemVolume.java':Path('app/src/io/tvos/SystemVolume.java').read_text(),
'io/tvos/AppLog.java':'package io.tvos;class AppLog {static void w(String s){}}',
'android/content/pm/PackageManager.java':'package android.content.pm;public class PackageManager {public static final int PERMISSION_GRANTED=0;}',
'android/os/Looper.java':'package android.os;public class Looper {public static Looper getMainLooper(){return new Looper();}}',
'android/os/SystemClock.java':'package android.os;public class SystemClock {public static long now;public static long uptimeMillis(){return now;}}',
'android/os/Handler.java':'''package android.os;import java.util.*;public class Handler {public Handler(Looper l){}static final Map<Runnable,Long> jobs=new HashMap<>();public boolean postDelayed(Runnable r,long d){jobs.put(r,SystemClock.now+d);return true;}public void removeCallbacks(Runnable r){jobs.remove(r);}public static void advance(long n){long end=SystemClock.now+n;while(true){Runnable next=null;long at=Long.MAX_VALUE;for(Map.Entry<Runnable,Long> e:jobs.entrySet())if(e.getValue()<at){next=e.getKey();at=e.getValue();}if(next==null||at>end)break;SystemClock.now=at;jobs.remove(next);next.run();}SystemClock.now=end;}public static int pending(){return jobs.size();}}''',
'android/view/KeyEvent.java':'''package android.view;public class KeyEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,KEYCODE_VOLUME_UP=24,KEYCODE_VOLUME_DOWN=25;final int action,code;public boolean cancelled;public KeyEvent(int a,int c){action=a;code=c;}public int getAction(){return action;}public int getKeyCode(){return code;}public boolean isCanceled(){return cancelled;}}''',
'android/media/AudioManager.java':'''package android.media;public class AudioManager {public static final int ADJUST_RAISE=1,ADJUST_LOWER=-1,USE_DEFAULT_STREAM_TYPE=-1,FLAG_SHOW_UI=1;public int calls,sum;public boolean fail;public void adjustSuggestedStreamVolume(int d,int s,int f){if(fail)throw new SecurityException();calls++;sum+=d;}}''',
'android/media/session/MediaSessionManager.java':'''package android.media.session;public class MediaSessionManager {public interface OnVolumeKeyLongPressListener {void onVolumeKeyLongPress(android.view.KeyEvent e);}public OnVolumeKeyLongPressListener listener;public int changes;public boolean fail;public void setOnVolumeKeyLongPressListener(OnVolumeKeyLongPressListener l,android.os.Handler h){if(fail)throw new SecurityException();listener=l;changes++;}}''',
'android/content/Context.java':'''package android.content;public class Context {public static final String MEDIA_SESSION_SERVICE="media",AUDIO_SERVICE="audio";public boolean permission=true;public final android.media.AudioManager audio=new android.media.AudioManager();public final android.media.session.MediaSessionManager manager=new android.media.session.MediaSessionManager();public int checkSelfPermission(String p){return permission?0:-1;}public Object getSystemService(String s){return s.equals(AUDIO_SERVICE)?audio:manager;}}''',
'io/tvos/SystemVolumeTest.java':'''package io.tvos;import android.content.*;import android.view.*;import android.os.*;public class SystemVolumeTest {
static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static void key(Context c,int a,int code){c.manager.listener.onVolumeKeyLongPress(new KeyEvent(a,code));}
public static void main(String[] args){Context c=new Context();SystemVolume v=new SystemVolume(c);c.permission=false;check(!v.start()&&c.manager.changes==0,"permission denied, no registration");c.permission=true;c.manager.fail=true;check(!v.start(),"registration failure observable");c.manager.fail=false;check(v.start()&&v.start()&&c.manager.changes==1,"idempotent registration");check(c.manager.listener.equals(c.manager.listener)&&!c.manager.listener.equals(new Object()),"proxy object identity");
key(c,0,24);check(c.audio.calls==1&&c.audio.sum==1,"hold callback first step");key(c,0,24);check(c.audio.calls==1,"native repeat does not duplicate timer");Handler.advance(84);check(c.audio.calls==1,"85ms interval");Handler.advance(1);check(c.audio.calls==2,"second step");key(c,1,24);int n=c.audio.calls;Handler.advance(1000);check(c.audio.calls==n&&Handler.pending()==0,"release ends timer");
key(c,0,25);check(c.audio.sum==1,"down direction");Handler.advance(10000);check(Handler.pending()==0&&c.audio.calls<n+101,"bounded lost release");n=c.audio.calls;key(c,0,25);Handler.advance(1000);check(c.audio.calls==n,"guard stays blocked until release");key(c,1,25);key(c,0,24);check(c.audio.calls==n+1,"new physical hold after release");
android.media.session.MediaSessionManager.OnVolumeKeyLongPressListener stale=c.manager.listener;v.close();v.close();check(c.manager.listener==null&&Handler.pending()==0,"unregister and cancel on screen/service stop");n=c.audio.calls;stale.onVolumeKeyLongPress(new KeyEvent(0,24));Handler.advance(1000);check(c.audio.calls==n,"late callback ignored");check(v.start(),"can resume");stale.onVolumeKeyLongPress(new KeyEvent(0,24));Handler.advance(100);check(c.audio.calls==n,"old proxy remains inactive after new registration");c.audio.fail=true;key(c,0,24);check(Handler.pending()==0,"audio failure stops scheduling");v.close();System.out.println("PASS: real privileged proxy, permission/registration denial, bounded hold, repeated events, release, stale callbacks, cleanup and resume");}}
'''}
with tempfile.TemporaryDirectory() as directory:
 root=Path(directory)
 for name,content in files.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',directory,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',directory,'io.tvos.SystemVolumeTest'],check=True)
